import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import toast from 'react-hot-toast';
import { Package, Plus, Search, X, DollarSign, Clock, CheckCircle, Trash2 } from 'lucide-react';

export default function Layby() {
  const { staff, storeId } = useAuth();
  const [laybys, setLaybys] = useState([]);
  const [customers, setCustomers] = useState([]);
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreate, setShowCreate] = useState(false);
  const [showPayment, setShowPayment] = useState(null);
  const [paymentAmount, setPaymentAmount] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCustomer, setSelectedCustomer] = useState('');
  const [cart, setCart] = useState([]);
  const [deposit, setDeposit] = useState('');
  const [dueDate, setDueDate] = useState('');
  const [notes, setNotes] = useState('');

  const isAdmin = staff?.role === 'admin' || staff?.role === 'manager';

  const loadLaybys = useCallback(async () => {
    if (!storeId) return;
    const { data } = await supabase
      .from('laybys')
      .select('*, customer:customers(name), staff:staff(full_name)')
      .eq('store_id', storeId)
      .order('created_at', { ascending: false });
    setLaybys(data || []);
    setLoading(false);
  }, [storeId]);

  const loadCustomers = async () => {
    const { data } = await supabase.from('customers').select('id,name').eq('store_id', storeId).order('name');
    setCustomers(data || []);
  };

  const loadProducts = async () => {
    const { data } = await supabase.from('products').select('*').eq('store_id', storeId).eq('is_active', true).order('name');
    setProducts(data || []);
  };

  useEffect(() => {
    if (storeId) { loadLaybys(); loadCustomers(); loadProducts(); }
  }, [storeId, loadLaybys]);

  const addToCart = (product) => {
    const existing = cart.find(i => i.id === product.id);
    if (existing) setCart(cart.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i));
    else setCart([...cart, { ...product, quantity: 1 }]);
  };

  const removeFromCart = (id) => setCart(cart.filter(i => i.id !== id));
  const updateCartQty = (id, delta) => {
    setCart(cart.map(i => {
      if (i.id === id) {
        const newQty = i.quantity + delta;
        if (newQty <= 0) return i;
        return { ...i, quantity: newQty };
      }
      return i;
    }));
  };

  const cartTotal = cart.reduce((sum, i) => sum + i.quantity * i.unit_price, 0);

  const handleCreateLayby = async (e) => {
    e.preventDefault();
    if (!cart.length) return toast.error('Add at least one product');
    if (!selectedCustomer) return toast.error('Select a customer');
    const depositVal = parseFloat(deposit) || 0;
    if (depositVal < 0) return toast.error('Deposit cannot be negative');
    try {
      const { data: layby, error } = await supabase.from('laybys').insert({
        store_id: storeId, customer_id: selectedCustomer, staff_id: staff.id,
        total_amount: cartTotal, deposit_amount: depositVal, status: 'active',
        due_date: dueDate || null, notes
      }).select().single();
      if (error) throw error;

      const items = cart.map(i => ({ layby_id: layby.id, product_id: i.id, quantity: i.quantity, unit_price: i.unit_price }));
      await supabase.from('layby_items').insert(items);
      for (const item of cart) await supabase.rpc('decrement_stock', { p_product_id: item.id, p_quantity: item.quantity });
      if (depositVal > 0) await supabase.from('layby_payments').insert({ layby_id: layby.id, amount: depositVal, payment_method: 'cash' });
      toast.success('Layby created');
      setShowCreate(false);
      setCart([]); setDeposit(''); setDueDate(''); setNotes(''); setSelectedCustomer('');
      loadLaybys();
    } catch (err) { toast.error(err.message); }
  };

  const handleAddPayment = async (e) => {
    e.preventDefault();
    const amount = parseFloat(paymentAmount);
    if (!amount || amount <= 0) return toast.error('Enter a valid amount');
    const layby = laybys.find(l => l.id === showPayment);
    if (!layby) return;
    const remaining = layby.total_amount - layby.deposit_amount;
    if (amount > remaining) return toast.error(`Amount exceeds remaining K${remaining.toFixed(2)}`);
    try {
      await supabase.from('layby_payments').insert({ layby_id: layby.id, amount, payment_method: 'cash' });
      const newDeposit = layby.deposit_amount + amount;
      await supabase.from('laybys').update({ deposit_amount: newDeposit }).eq('id', layby.id);
      if (newDeposit >= layby.total_amount) {
        await supabase.from('laybys').update({ status: 'completed' }).eq('id', layby.id);
        toast.success('Layby fully paid!');
      } else toast.success(`Payment of K${amount.toFixed(2)} recorded`);
      setShowPayment(null); setPaymentAmount(''); loadLaybys();
    } catch (err) { toast.error(err.message); }
  };

  const cancelLayby = async (layby) => {
    if (!window.confirm('Cancel this layby? Stock will be returned.')) return;
    try {
      const { data: items } = await supabase.from('layby_items').select('product_id,quantity').eq('layby_id', layby.id);
      for (const item of items || []) await supabase.rpc('increment_stock', { p_product_id: item.product_id, p_quantity: item.quantity });
      await supabase.from('laybys').update({ status: 'cancelled' }).eq('id', layby.id);
      toast.success('Layby cancelled'); loadLaybys();
    } catch (err) { toast.error(err.message); }
  };

  const filteredLaybys = laybys.filter(l => l.customer?.name?.toLowerCase().includes(searchTerm.toLowerCase()));
  if (loading) return <div className="p-8">Loading laybys...</div>;

  const currency = 'K';

  return (
    <div className="p-4 h-full overflow-y-auto">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold"><Package className="inline mr-2" />Lay‑by</h1>
        {isAdmin && (
          <button onClick={() => setShowCreate(true)} className="bg-green-600 text-white px-4 py-2 rounded-lg flex items-center gap-2">
            <Plus size={18} /> New Lay‑by
          </button>
        )}
      </div>
      <div className="mb-4 relative">
        <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
        <input placeholder="Search by customer..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-10 p-2 border rounded-lg" />
      </div>
      <div className="space-y-4">
        {filteredLaybys.length === 0 ? (
          <div className="bg-white rounded-xl shadow p-12 text-center"><Package size={48} className="mx-auto mb-4 opacity-30"/><p>No lay‑bys found</p></div>
        ) : (
          filteredLaybys.map(l => {
            const remaining = l.total_amount - l.deposit_amount;
            const progressPercent = l.total_amount > 0 ? (l.deposit_amount / l.total_amount) * 100 : 0;
            return (
              <div key={l.id} className="bg-white rounded-xl shadow p-5">
                <div className="flex justify-between items-start">
                  <div><p className="font-bold text-lg">{l.customer?.name || 'Walk-in'}</p><p className="text-sm text-gray-500">Staff: {l.staff?.full_name}</p></div>
                  <span className={`px-3 py-1 rounded-full text-xs font-semibold ${l.status === 'active' ? 'bg-blue-100 text-blue-800' : l.status === 'completed' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>{l.status}</span>
                </div>
                <div className="mt-3 grid grid-cols-2 gap-2 text-sm">
                  <div>Total: <span className="font-bold">{currency}{l.total_amount?.toFixed(2)}</span></div>
                  <div>Paid: <span className="font-bold text-green-600">{currency}{l.deposit_amount?.toFixed(2)}</span></div>
                  <div>Remaining: <span className="font-bold text-red-600">{currency}{remaining.toFixed(2)}</span></div>
                  {l.due_date && <div>Due: {new Date(l.due_date).toLocaleDateString()}</div>}
                </div>
                <div className="mt-3 w-full bg-gray-200 rounded-full h-2.5"><div className="bg-green-600 h-2.5 rounded-full" style={{width: `${progressPercent}%`}}></div></div>
                {l.status === 'active' && isAdmin && (
                  <div className="mt-4 flex gap-2">
                    <button onClick={() => { setShowPayment(l.id); setPaymentAmount(''); }} className="px-3 py-1.5 bg-blue-600 text-white rounded text-sm">Add Payment</button>
                    <button onClick={() => cancelLayby(l)} className="px-3 py-1.5 bg-red-600 text-white rounded text-sm">Cancel</button>
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>

      {showCreate && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl w-full max-w-4xl max-h-[90vh] overflow-auto">
            <div className="p-4 border-b flex justify-between"><h2 className="text-xl font-bold">New Lay‑by</h2><button onClick={() => setShowCreate(false)}><X/></button></div>
            <div className="flex flex-col lg:flex-row">
              <div className="flex-1 p-4 border-r">
                <div className="grid grid-cols-2 gap-2 max-h-96 overflow-y-auto">
                  {products.map(p => (
                    <button key={p.id} onClick={() => addToCart(p)} className="p-2 bg-gray-50 border rounded text-left text-sm">
                      <div className="font-medium truncate">{p.name}</div>
                      <div className="text-xs text-gray-500">{currency}{p.unit_price?.toFixed(2)}</div>
                    </button>
                  ))}
                </div>
              </div>
              <div className="w-full lg:w-96 p-4 space-y-3">
                <div>
                  <label className="block text-sm mb-1">Customer</label>
                  <select value={selectedCustomer} onChange={e => setSelectedCustomer(e.target.value)} className="w-full p-2 border rounded">
                    <option value="">Select customer</option>
                    {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
                <div className="max-h-60 overflow-y-auto">
                  {cart.map(item => (
                    <div key={item.id} className="flex items-center justify-between py-1 border-b">
                      <span className="text-sm truncate flex-1">{item.name}</span>
                      <div className="flex items-center gap-1">
                        <button onClick={() => updateCartQty(item.id, -1)} className="p-0.5 bg-gray-200 rounded"><X size={12}/></button>
                        <span className="w-6 text-center text-sm">{item.quantity}</span>
                        <button onClick={() => updateCartQty(item.id, 1)} className="p-0.5 bg-gray-200 rounded">+</button>
                      </div>
                      <span className="text-sm w-16 text-right">{currency}{(item.quantity * item.unit_price).toFixed(2)}</span>
                      <button onClick={() => removeFromCart(item.id)} className="p-0.5 text-red-500"><Trash2 size={14}/></button>
                    </div>
                  ))}
                </div>
                <div className="font-bold text-lg">Total: {currency}{cartTotal.toFixed(2)}</div>
                <input type="number" placeholder="Deposit" value={deposit} onChange={e => setDeposit(e.target.value)} className="w-full p-2 border rounded" />
                <input type="date" value={dueDate} onChange={e => setDueDate(e.target.value)} className="w-full p-2 border rounded" />
                <textarea placeholder="Notes" value={notes} onChange={e => setNotes(e.target.value)} className="w-full p-2 border rounded" rows={2} />
                <button onClick={handleCreateLayby} className="w-full bg-green-600 text-white py-2 rounded">Create Lay‑by</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {showPayment && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl w-full max-w-sm">
            <div className="p-4 border-b flex justify-between"><h2 className="text-lg font-bold">Add Payment</h2><button onClick={() => setShowPayment(null)}><X/></button></div>
            <form onSubmit={handleAddPayment} className="p-4 space-y-4">
              {(() => { const layby = laybys.find(l => l.id === showPayment); const remaining = layby ? layby.total_amount - layby.deposit_amount : 0; return (<p className="text-sm">Remaining: <span className="font-bold">{currency}{remaining.toFixed(2)}</span></p>); })()}
              <input type="number" step="0.01" placeholder="Amount" value={paymentAmount} onChange={e => setPaymentAmount(e.target.value)} className="w-full p-2 border rounded" required />
              <div className="flex gap-2">
                <button type="button" onClick={() => setShowPayment(null)} className="flex-1 py-2 border rounded">Cancel</button>
                <button type="submit" className="flex-1 py-2 bg-blue-600 text-white rounded">Record Payment</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
